#!/usr/bin/env python3
r"""export_skills.py: write the 71 custom skills snapshotted on 2026-10-05 into a folder.

Python 3.8+, standard library only, no network. The skills are embedded in this file.

  python export_skills.py                 write to the default destination below
  python export_skills.py --dry-run       show what would change, write nothing
  python export_skills.py --list          print the skill names inside this script
  python export_skills.py --only ui-contract,assay
  python export_skills.py --dest D:\other\skills
  python export_skills.py --fix-names     rewrite a frontmatter name that differs from its folder name

Each skill is written as <dest>/<skill-name>/SKILL.md (plus any bundled files), the layout the
therantai-skills repo expects under skills/. A skill folder whose content differs is replaced,
a folder that already matches is left untouched, and nothing else in <dest> is touched.
Anthropic-provided skills (docx, pdf, pptx, xlsx, chrome-browser, ...) are not included.
"""
import argparse
import base64
import hashlib
import io
import os
import pathlib
import re
import shutil
import stat
import sys
import tempfile
import zipfile

DEFAULT_DEST = r"C:\Users\meetv\Music\github-files\skills"
PAYLOAD_SHA256 = "20057877f21d6e2c71bc660b67145653543dfb4df341c78ae3f4bab7f11924f6"
NAME_OK = re.compile(r"[a-z0-9][a-z0-9-]*")


def die(msg):
    print(f"export_skills: {msg}", file=sys.stderr)
    sys.exit(1)


def sha(data):
    return hashlib.sha256(data).hexdigest()


def load_payload():
    """Decode the embedded archive into {skill_name: {relative_path: bytes}}."""
    raw = base64.b64decode("".join(PAYLOAD.split()))
    if sha(raw) != PAYLOAD_SHA256:
        die("embedded payload is corrupted (checksum mismatch); re-download this script")
    skills = {}
    with zipfile.ZipFile(io.BytesIO(raw)) as zf:
        for info in zf.infolist():
            if info.is_dir():
                continue
            parts = pathlib.PurePosixPath(info.filename).parts
            if len(parts) < 2 or ".." in parts or info.filename.startswith("/") \
                    or "\\" in info.filename or any(":" in p for p in parts):
                die(f"unsafe path in payload: {info.filename}")
            if not NAME_OK.fullmatch(parts[0]):
                die(f"unexpected skill folder name in payload: {parts[0]}")
            skills.setdefault(parts[0], {})["/".join(parts[1:])] = zf.read(info)
    return skills


def frontmatter_name(data):
    m = re.match(rb"---\r?\n(.*?)\r?\n---", data, re.S)
    if not m:
        return None
    n = re.search(rb"^name:[ \t]*(.+?)[ \t]*$", m.group(1), re.M)
    return n.group(1).strip(b"\"'").decode("utf-8", "replace") if n else None


def fix_name(data, folder):
    m = re.match(rb"---\r?\n(.*?)\r?\n---", data, re.S)
    fm = re.sub(rb"^name:.*$", b"name: " + folder.encode(), m.group(1), count=1, flags=re.M)
    return data[:m.start(1)] + fm + data[m.end(1):]


def resolve_dest(raw):
    m = re.match(r"^([A-Za-z]):[\\/]*(.*)$", raw)
    if os.name != "nt" and m:  # Windows-style path on WSL / Linux / macOS
        mount = pathlib.Path("/mnt") / m.group(1).lower()
        if mount.is_dir():
            return mount / pathlib.PurePosixPath(m.group(2).replace("\\", "/"))
        die("the destination is a Windows path but this is not Windows; pass --dest with a local folder")
    return pathlib.Path(raw)


def tree_hashes(folder):
    out = {}
    for f in folder.rglob("*"):
        if f.is_file():
            out[f.relative_to(folder).as_posix()] = sha(f.read_bytes())
    return out


def rmtree(path):
    def force(func, p, _exc):
        os.chmod(p, stat.S_IWRITE)
        func(p)
    if sys.version_info >= (3, 12):
        shutil.rmtree(path, onexc=force)
    else:
        shutil.rmtree(path, onerror=force)


def main():
    ap = argparse.ArgumentParser(description="Export the embedded custom skills to a folder.")
    ap.add_argument("--dest", default=DEFAULT_DEST, help=f"destination folder (default: {DEFAULT_DEST})")
    ap.add_argument("--dry-run", action="store_true", help="report what would change; write nothing")
    ap.add_argument("--list", action="store_true", help="print the embedded skill names and exit")
    ap.add_argument("--only", help="comma-separated skill names to export")
    ap.add_argument("--fix-names", action="store_true",
                    help="rewrite a frontmatter name that differs from its folder name")
    args = ap.parse_args()

    skills = load_payload()
    if args.only:
        want = [n.strip() for n in args.only.split(",") if n.strip()]
        unknown = [n for n in want if n not in skills]
        if unknown:
            die("unknown skill(s): " + ", ".join(unknown))
        skills = {n: skills[n] for n in want}
    if args.list:
        print("\n".join(sorted(skills)))
        print(f"{len(skills)} skills", file=sys.stderr)
        return 0

    mismatched = []
    for name, files in skills.items():
        found = frontmatter_name(files["SKILL.md"]) if "SKILL.md" in files else None
        if found != name:
            mismatched.append((name, found))
            if args.fix_names and found is not None:
                files["SKILL.md"] = fix_name(files["SKILL.md"], name)

    dest = resolve_dest(args.dest)
    if dest.exists() and not dest.is_dir():
        die(f"{dest} exists and is not a folder")

    expected = {n: {rel: sha(b) for rel, b in files.items()} for n, files in skills.items()}
    plan = {"new": [], "updated": [], "unchanged": []}
    for name in sorted(skills):
        target = dest / name
        if not target.exists():
            plan["new"].append(name)
        elif tree_hashes(target) == expected[name]:
            plan["unchanged"].append(name)
        else:
            plan["updated"].append(name)

    print(f"destination: {dest}")
    print(f"skills: {len(skills)} | new {len(plan['new'])} | updated {len(plan['updated'])} "
          f"| unchanged {len(plan['unchanged'])}")
    if plan["updated"]:
        print("will replace: " + ", ".join(plan["updated"]))
    if mismatched and not args.fix_names:
        for name, found in mismatched:
            print(f"WARNING: {name}/SKILL.md has frontmatter name {found!r}, which differs from its folder name; "
                  "the repo lint will reject it. Re-run with --fix-names to correct it.")
    elif mismatched:
        print("fixed frontmatter name in: " + ", ".join(n for n, _ in mismatched))
    if args.dry_run:
        print("dry run: nothing written")
        return 0

    todo = plan["new"] + plan["updated"]
    if todo:
        dest.mkdir(parents=True, exist_ok=True)
        stage = pathlib.Path(tempfile.mkdtemp(prefix=".export-tmp-", dir=str(dest)))
        try:
            for name in todo:
                for rel, data in skills[name].items():
                    p = stage / name / rel
                    p.parent.mkdir(parents=True, exist_ok=True)
                    p.write_bytes(data)
            for name in todo:
                target = dest / name
                if target.exists():
                    rmtree(target)
                os.replace(stage / name, target)
        finally:
            rmtree(stage)

    bad = [n for n in skills if tree_hashes(dest / n) != expected[n]]
    if bad:
        die("verification failed for: " + ", ".join(bad))
    nfiles = sum(len(v) for v in expected.values())
    print(f"done: {len(skills)} skills ({nfiles} files) verified in {dest}")
    return 0


